rith + +end + +end MIPStarRE.QPBT diff --git a/MIPStarRE/QPBT/Combining/Points.lean b/MIPStarRE/QPBT/Combining/Points.lean index ee1d8bbd..280cac0b 100644 --- a/MIPStarRE/QPBT/Combining/Points.lean +++ b/MIPStarRE/QPBT/Combining/Points.lean @@ -1,3 +1,4 @@ +import MIPStarRE.QPBT.Combining.Points.Closeness  import MIPStarRE.QPBT.Combining.PointsDataProcessing    /-! @@ -17,7 +18,7 @@ The coarse-graining is `lem:qld-4-12` in the same blueprint, with paper source  `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:993-1011`.  -/   -open scoped BigOperators +open scoped BigOperators Matrix MatrixOrder ComplexOrder    namespace MIPStarRE.QPBT   @@ -44,16 +45,200 @@ noncomputable def extendedQ {P : AdmissibleParams} {ε δ : ℝ}      Measurement (PauliScalar P) (S.ExpandedLocalSpace side) :=    (points.Q side x z).postprocess fun ab => alpha * ab.1 + beta * ab.2   +/-- The first postprocessed joint-point effect is its X marginal sum. +This formalization-only identity is the definition preceding +`eq:qld-qxz-close-to-point`, paper +`references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:917-932`. -/ +theorem postprocess_fst_effect {P : AdmissibleParams} {ε δQ : ℝ} +    {S : ProjectiveSetting P ε} (points : CombinedPointsWitness S δQ) +    (side : PlayerSide) (x z : Fin P.m -> PauliScalar P) (a : PauliScalar P) : +    ((points.Q side x z).postprocess Prod.fst).effect a = +      ∑ b, (points.Q side x z).effect (a, b) := by +  classical +  change (∑ pair ∈ Finset.univ.filter (fun pair => pair.1 = a), +    (points.Q side x z).effect pair) = _ +  simp only [Finset.sum_filter, Fintype.sum_prod_type] +  rw [Finset.sum_comm] +  simp + +/-- The second postprocessed joint-point effect is its Z marginal sum. +This formalization-only identity is `eq:qld-qxz-close-to-point-2`, paper +`references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:933-935`. -/ +theorem postprocess_snd_effect {P : AdmissibleParams} {ε δQ : ℝ} +    {S : ProjectiveSetting P ε} (points : CombinedPointsWitness S δQ) +    (side : PlayerSide) (x z : Fin P.m -> PauliScalar P) (b : PauliScalar P) : +    ((points.Q side x z).postprocess Prod.snd).effect b = +      ∑ a, (points.Q side x z).effect (a, b) := by +  classical +  change (∑ pair ∈ Finset.univ.filter (fun pair => pair.2 = b), +    (points.Q side x z).effect pair) = _ +  simp [Finset.sum_filter, Fintype.sum_prod_type] +  end CombinedPointsWitness    /-- Construction of the projective joint point measurements of  `lem:qld-4-10`, paper lines 689--709.  The witness retains both ordered -products and all four directed heterogeneous placement comparisons. -/ +products and all four directed heterogeneous placement comparisons. + +The construction works on the original expanded local spaces: the sandwich +POVM `M^Z_b M^X_a M^Z_b`, formed directly with outcomes in `F_q × F_q`, is +close to the ordered product by the field-valued commutation estimate +(`expPoint_comm`), self-consistent between opposite placements +(`sandwich_offDiagonal_le_sandwichDefectBound`), and is made projective for +each point pair by the orthonormalization lemma +(`exists_projective_close_sandwich`); the three consistency conclusions follow +by the triangle inequality (`chain_bounds`).  The source's route through the +binary refinements and the quantum linearity theorem is not used, because +that route needs zero-state padding of the strategy, which is not part of the +setting; see `rem:linearity-import` and +`docs/paper-gaps/qpbt_linearity-theorem-quotation.tex`.  The error is +`K ε^{1/8}` for a universal constant `K`. -/  theorem exists_combinedPointsWitness :      ∃ deltaQ : ℝ -> ℝ, IsPolyErr deltaQ ∧        ∀ (P : AdmissibleParams) (ε : ℝ) (S : ProjectiveSetting P ε),          Nonempty (CombinedPointsWitness S (deltaQ ε)) := by -  sorry +  obtain ⟨C₀, hC₀, h₀⟩ := ProjectiveSetting.avg_sandwichDefectBound_le +  obtain ⟨C₁, hC₁, h₁⟩ := ProjectiveSetting.sandwichPoint_ordered_dist_le +  obtain ⟨C₂, hC₂, h₂⟩ := ProjectiveSetting.expPoint_comm +  obtain ⟨C₃, hC₃, h₃⟩ := ProjectiveSetting.ordered_cross_dist_le +  -- the universal constant of the final error `K ε^{1/8}` +  set K : ℝ := 12 * (440 * (2 * C₀)) + 20 * C₁ + 16 * C₃ + 4 * C₂ with hK +  have hK4 : (4 : ℝ) ≤ K := by rw [hK]; nlinarith +  refine ⟨fun ε => K * Real.rpow ε (1 / 8 : ℝ), +    ⟨K, 1 / 8, by linarith, by norm_num, fun x hx => +      ⟨mul_nonneg (by linarith) (Real.rpow_nonneg hx _), le_rfl⟩⟩, ?_⟩ +  intro P ε S +  have hε : (0 : ℝ) ≤ ε := by +    have hv := WinImplications.strategy_value_le_one S.toStrategy +    have hw := S.win +    linarith +  obtain ⟨Qa, hQa, hQaR⟩ := S.exists_projective_close_sandwich_alice +  obtain ⟨Qb, hQb, hQbR⟩ := S.exists_projective_close_sandwich_bob +  -- the joint measurements on the two sides +  let Q : (side : PlayerSide) → PointPair P → +      Measurement (PauliScalar P × PauliScalar P) (S.ExpandedLocalSpace side) := +    fun side => match side with +      | .alice => Qa +      | .bob => Qb +  have hQproj : ∀ side xz, MIPStarRE.QPBT.Measurement.IsProjective (Q side xz) := by +    intro side xz +    cases side +    · exact hQa xz +    · exact hQb xz +  -- the closeness of `Q` to the sandwich on every placement +  set η : ℝ := 440 * Real.rpow (C₀ * (ε + Real.sqrt ε)) (1 / 4 : ℝ) with hη +  have hbound : ∀ p₁ p₂ : Placement, p₁.IsOpposite p₂ → +      220 * Real.rpow (avgOver (uniformDistribution (PointPair P)) +        (S.sandwichDefectBound p₁ p₂)) (1 / 4 : ℝ) ≤ η := by +    intro p₁ p₂ hopp +    have hnn : 0 ≤ avgOver (uniformDistribution (PointPair P)) +        (S.sandwichDefectBound p₁ p₂) := +      avgOver_nonneg _ _ (S.sandwichDefectBound_nonneg p₁ p₂) +    have hr : Real.rpow (avgOver (uniformDistribution (PointPair P)) +        (S.sandwichDefectBound p₁ p₂)) (1 / 4 : ℝ) ≤ +        Real.rpow (C₀ * (ε + Real.sqrt ε)) (1 / 4 : ℝ) := +      Real.rpow_le_rpow hnn (h₀ P ε S p₁ p₂ hopp) (by norm_num) +    have hr0 : 0 ≤ Real.rpow (C₀ * (ε + Real.sqrt ε)) (1 / 4 : ℝ) := +      Real.rpow_nonneg (by positivity) _ +    rw [hη] +    nlinarith +  have hQR : ∀ p : Placement, opFamilyDistSq (uniformDistribution (PointPair P)) +      (fun xz (ab : PauliScalar P × PauliScalar P) => +        S.place p ((Q p.side xz).effect ab)) +      (fun xz ab => S.place p ((S.sandwichPoint p.side xz.1 xz.2).effect ab)) +      S.psiHat ≤ η := by +    intro p +    cases p +    · exact le_trans hQaR (hbound .AA' .BA'' trivial) +    · exact le_trans hQbR (hbound .BA'' .AA' trivial) +    · rw [ProjectiveSetting.opFamilyDistSq_place_BB'_eq_BA''] +      exact le_trans hQbR (hbound .BA'' .AA' trivial) +    · rw [ProjectiveSetting.opFamilyDistSq_place_AB''_eq_AA'] +      exact le_trans hQaR (hbound .AA' .BA'' trivial) +  have hchain := fun (p₁ p₂ : Placement) (hopp : p₁.IsOpposite p₂) => +    S.chain_bounds Q η C₁ C₂ C₃ hQR (h₁ P ε S) (h₂ P ε S) (h₃ P ε S) p₁ p₂ hopp +  -- the numeric bound on the longest chain, in the two regimes of `ε` +  have hηnn : 0 ≤ η := by +    rw [hη] +    exact mul_nonneg (by norm_num) +      (Real.rpow_nonneg (mul_nonneg (by linarith) (add_nonneg hε (Real.sqrt_nonneg ε))) _) +  have hs : 0 ≤ Real.sqrt ε := Real.sqrt_nonneg ε +  have htotal : 12 * η + 20 * (C₁ * Real.sqrt ε) + 16 * (C₃ * ε) + +      4 * (C₂ * Real.sqrt ε) ≤ K * Real.rpow ε (1 / 8 : ℝ) ∨ 1 < ε := by +    by_cases hε1 : ε ≤ 1 +    · left +      obtain ⟨hε8, hs8, hq8⟩ := error_terms_le_rpow_eighth hε hε1 hC₀ +      rw [hη, hK] +      nlinarith [mul_le_mul_of_nonneg_left hq8 (by norm_num : (0 : ℝ) ≤ 440), +        mul_le_mul_of_nonneg_left hs8 (by linarith : (0 : ℝ) ≤ C₁), +        mul_le_mul_of_nonneg_left hs8 (by linarith : (0 : ℝ) ≤ C₂), +        mul_le_mul_of_nonneg_left hε8 (by linarith : (0 : ℝ) ≤ C₃)] +    · right +      exact lt_of_not_ge hε1 +  have hK8 : 1 < ε → (4 : ℝ) ≤ K * Real.rpow ε (1 / 8 : ℝ) := by +    intro hε1 +    have h1 : (1 : ℝ) ≤ Real.rpow ε (1 / 8 : ℝ) := +      Real.one_le_rpow (le_of_lt hε1) (by norm_num) +    nlinarith +  have hsub1 : 2 * η + 4 * (C₁ * Real.sqrt ε) + 4 * (C₃ * ε) ≤ +      12 * η + 20 * (C₁ * Real.sqrt ε) + 16 * (C₃ * ε) + 4 * (C₂ * Real.sqrt ε) := by +    nlinarith +  have hsub2 : 4 * η + 8 * (C₁ * Real.sqrt ε) + 8 * (C₃ * ε) + +      2 * (C₂ * Real.sqrt ε) ≤ +      12 * η + 20 * (C₁ * Real.sqrt ε) + 16 * (C₃ * ε) + 4 * (C₂ * Real.sqrt ε) := by +    nlinarith +  -- square-summability of the families, for the trivial bound +  have hsqQ : ∀ (p : Placement) (xz : PointPair P), +      (∑ ab : PauliScalar P × PauliScalar P, +        (S.place p ((Q p.side xz).effect ab))ᴴ * +          S.place p ((Q p.side xz).effect ab)) ≤ 1 := +    fun p xz => S.sum_place_effect_conjTranspose_mul_self_le_one p _ (hQproj p.side xz) +  have hsqXZ : ∀ (p : Placement) (xz : PointPair P), +      (∑ ab : PauliScalar P × PauliScalar P, +        (S.place p ((S.pointMeasExp p.side .X xz.1).effect ab.1 * +          (S.pointMeasExp p.side .Z xz.2).effect ab.2))ᴴ * +        S.place p ((S.pointMeasExp p.side .X xz.1).effect ab.1 * +          (S.pointMeasExp p.side .Z xz.2).effect ab.2)) ≤ 1 := by +    intro p xz +    refine le_of_eq ?_ +    simp only [ProjectiveSetting.place_mul] +    exact sum_mul_conjTranspose_mul_self_eq_one +      (S.placedMeasurement p (S.pointMeasExp p.side .X xz.1)) +      (S.placedMeasurement p (S.pointMeasExp p.side .Z xz.2)) +      (S.placedMeasurement_isProjective p _ (S.pointMeasExp_isProjective _ _ _)) +      (S.placedMeasurement_isProjective p _ (S.pointMeasExp_isProjective _ _ _)) +  have hsqZX : ∀ (p : Placement) (xz : PointPair P), +      (∑ ab : PauliScalar P × PauliScalar P, +        (S.place p ((S.pointMeasExp p.side .Z xz.2).effect ab.2 * +          (S.pointMeasExp p.side .X xz.1).effect ab.1))ᴴ * +        S.place p ((S.pointMeasExp p.side .Z xz.2).effect ab.2 * +          (S.pointMeasExp p.side .X xz.1).effect ab.1)) ≤ 1 := by +    intro p xz +    refine le_of_eq ?_ +    simp only [ProjectiveSetting.place_mul] +    exact sum_mul_conjTranspose_mul_self_eq_one' +      (S.placedMeasurement p (S.pointMeasExp p.side .X xz.1)) +      (S.placedMeasurement p (S.pointMeasExp p.side .Z xz.2)) +      (S.placedMeasurement_isProjective p _ (S.pointMeasExp_isProjective _ _ _)) +      (S.placedMeasurement_isProjective p _ (S.pointMeasExp_isProjective _ _ _)) +  refine ⟨CombinedPointsWitness.mk (fun side x z => Q side (x, z)) ?_ ?_ ?_ ?_⟩ +  · intro side x z +    exact hQproj side (x, z) +  · intro p₁ p₂ hopp +    rcases htotal with htot | hε1 +    · exact le_trans (hchain p₁ p₂ hopp).2.2 htot +    · exact le_trans (opFamilyDistSq_uniform_le_four _ _ S.psiHat S.psiHat_norm +        (fun xz => hsqQ p₁ xz) (fun xz => hsqQ p₂ xz)) (hK8 hε1) +  · intro p₁ p₂ hopp +    rcases htotal with htot | hε1 +    · exact le_trans (hchain p₁ p₂ hopp).1 (le_trans hsub1 htot) +    · exact le_trans (opFamilyDistSq_uniform_le_four _ _ S.psiHat S.psiHat_norm +        (fun xz => hsqQ p₁ xz) (fun xz => hsqXZ p₂ xz)) (hK8 hε1) +  · intro p₁ p₂ hopp +    rcases htotal with htot | hε1 +    · exact le_trans (hchain p₁ p₂ hopp).2.1 (le_trans hsub2 htot) +    · exact le_trans (opFamilyDistSq_uniform_le_four _ _ S.psiHat S.psiHat_norm +        (fun xz => hsqQ p₁ xz) (fun xz => hsqZX p₂ xz)) (hK8 hε1)    /-- Register placement distributes over a filtered outcome sum. -/  private theorem place_finset_sum {P : AdmissibleParams} {ε : ℝ} diff --git a/MIPStarRE/QPBT/Combining/Points/Absorption.lean b/MIPStarRE/QPBT/Combining/Points/Absorption.lean new file mode 100644 index 00000000..8fc53e21 --- /dev/null +++ b/MIPStarRE/QPBT/Combining/Points/Absorption.lean @@ -0,0 +1,107 @@ +import MIPStarRE.QPBT.Combining.Points.Closeness +import MIPStarRE.QPBT.Combining.Witnesses + +/-! +# Absorption estimates for combined point measurements + +This module proves the first projection step used to compare a joint point +measurement with the corresponding marginal point measurement.  Projectivity +makes the complementary projection contractive, and the two ordered +consistency fields of `CombinedPointsWitness` supply the resulting averaged +bounds. + +## References + +Paper `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:902-915`. +-/ + +open scoped BigOperators Matrix MatrixOrder ComplexOrder + +namespace MIPStarRE.QPBT + +open MIPStarRE.LDT hiding Measurement +open MIPStarRE.Quantum + +noncomputable section + +/-- Removing the component outside a projective effect is a contraction. +This is the projection step preceding `eq:qqm`, paper +`14_analysis_of_the_pauli_basis_test.tex:902-915`. No commutation of the +two operators being compared is required. -/ +theorem norm_sub_projective_mul_sq_le {α ι : Type*} [Fintype α] +    [Fintype ι] [DecidableEq ι] (M : Quantum.Measurement α ι) +    (hM : Measurement.IsProjective M) (a : α) (A D : Op ι) +    (ψ : EuclideanSpace ℂ ι) : +    ‖applyOperatorToState (A - M.effect a * A) ψ‖ ^ 2 ≤ +      ‖applyOperatorToState (A - M.effect a * D) ψ‖ ^ 2 := by +  have hidem := (hM a).isIdempotentElem.eq +  have hgram : (1 - M.effect a)ᴴ * (1 - M.effect a) ≤ 1 := by +    rw [Matrix.conjTranspose_sub, Matrix.conjTranspose_one, +      (hM a).isSelfAdjoint.isHermitian.eq] +    calc +      (1 - M.effect a) * (1 - M.effect a) = 1 - M.effect a := by +        simp only [sub_mul, mul_sub, one_mul, mul_one, hidem] +        abel +      _ ≤ 1 := sub_le_self _ (M.pos a) +  have heq : A - M.effect a * A = +      (1 - M.effect a) * (A - M.effect a * D) := by +    simp only [sub_mul, mul_sub, one_mul, ← mul_assoc, hidem] +    abel +  rw [heq, DistanceCalculus.applyOperatorToState_mul] +  exact pow_le_pow_left₀ (norm_nonneg _) +    (MagicSquareRigidity.norm_applyOperatorToState_le hgram _) 2 + +/-- The joint point witness absorbs the opposite X point projector with +error at most its actual parameter. This is the X counterpart of the first +projection step of `lem:qld-xz-lines`, paper lines 902--915, obtained from +`consistent_XZ` rather than from an assumed marginal identity. -/ +theorem CombinedPointsWitness.absorb_X_le {P : AdmissibleParams} {ε δQ : ℝ} +    {S : ProjectiveSetting P ε} (points : CombinedPointsWitness S δQ) +    (p1 p2 : Placement) (hopp : p1.IsOpposite p2) : +    opFamilyDistSq +      (uniformDistribution +        ((Fin P.m → PauliScalar P) × (Fin P.m → PauliScalar P))) +      (fun xz ab => S.place p1 ((points.Q p1.side xz.1 xz.2).effect ab)) +      (fun xz ab => S.place p2 ((S.pointMeasExp p2.side .X xz.1).effect ab.1) * +        S.place p1 ((points.Q p1.side xz.1 xz.2).effect ab)) S.psiHat ≤ δQ := by +  refine le_trans ?_ (points.consistent_XZ p1 p2 hopp) +  unfold opFamilyDistSq +  apply avgOver_mono +  intro xz +  apply Finset.sum_le_sum +  intro ab _ +  simpa only [ProjectiveSetting.placedMeasurement_effect, ProjectiveSetting.place_mul] +    using norm_sub_projective_mul_sq_le +      (S.placedMeasurement p2 (S.pointMeasExp p2.side .X xz.1)) +      (S.placedMeasurement_isProjective p2 _ (S.pointMeasExp_isProjective _ _ _)) +      ab.1 (S.place p1 ((points.Q p1.side xz.1 xz.2).effect ab)) +      (S.place p2 ((S.pointMeasExp p2.side .Z xz.2).effect ab.2)) S.psiHat + +/-- The joint point witness absorbs the opposite Z point projector with +error at most its actual parameter. This is the first projection step in +`lem:qld-xz-lines`, paper lines 902--915, derived from `consistent_ZX`. -/ +theorem CombinedPointsWitness.absorb_Z_le {P : AdmissibleParams} {ε δQ : ℝ} +    {S : ProjectiveSetting P ε} (points : CombinedPointsWitness S δQ) +    (p1 p2 : Placement) (hopp : p1.IsOpposite p2) : +    opFamilyDistSq +      (uniformDistribution +        ((Fin P.m → PauliScalar P) × (Fin P.m → PauliScalar P))) +      (fun xz ab => S.place p1 ((points.Q p1.side xz.1 xz.2).effect ab)) +      (fun xz ab => S.place p2 ((S.pointMeasExp p2.side .Z xz.2).effect ab.2) * +        S.place p1 ((points.Q p1.side xz.1 xz.2).effect ab)) S.psiHat ≤ δQ := by +  refine le_trans ?_ (points.consistent_ZX p1 p2 hopp) +  unfold opFamilyDistSq +  apply avgOver_mono +  intro xz +  apply Finset.sum_le_sum +  intro ab _ +  simpa only [ProjectiveSetting.placedMeasurement_effect, ProjectiveSetting.place_mul] +    using norm_sub_projective_mul_sq_le +      (S.placedMeasurement p2 (S.pointMeasExp p2.side .Z xz.2)) +      (S.placedMeasurement_isProjective p2 _ (S.pointMeasExp_isProjective _ _ _)) +      ab.2 (S.place p1 ((points.Q p1.side xz.1 xz.2).effect ab)) +      (S.place p2 ((S.pointMeasExp p2.side .X xz.1).effect ab.1)) S.psiHat + +end + +end MIPStarRE.QPBT diff --git a/MIPStarRE/QPBT/Combining/Points/Closeness.lean b/MIPStarRE/QPBT/Combining/Points/Closeness.lean new file mode 100644 index 00000000..6fb2a3cb --- /dev/null +++ b/MIPStarRE/QPBT/Combining/Points/Closeness.lean @@ -0,0 +1,301 @@ +import MIPStarRE.QPBT.Combining.Points.Orthonormalization + +/-! +# Closeness estimates for the combined point measurements + +Given projective measurements `Q^{x,z}` on each player's expanded local space +that are close to the sandwich POVMs on the placements where they were +constructed, this file assembles the three conclusions of `lem:qld-4-10` on +every pair of opposite placements by the triangle inequality along +`Q ≈ R ≈ M^Z M^X ≈ M^X M^Z` and the cross-placement consistency of the +ordered products.  It also records the trivial bound `4` on the state-dependent +distance of two square-summable families, used when the test error exceeds +one, and the elementary estimate collapsing the error terms `ε`, `√ε`, and +`(ε + √ε)^{1/4}` into a single power `ε^{1/8}` when `ε ≤ 1`. + +## References + +Paper `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:838-881` +(self-consistency and consistency with `M̂` in the proof of `lem:qld-4-10`), +blueprint `blueprint/src/chapter/ch15_qpbt_combining.tex:803-960`; the route +is explained in `docs/paper-gaps/qpbt_linearity-theorem-quotation.tex`. +-/ + +open scoped BigOperators Matrix MatrixOrder ComplexOrder + +namespace MIPStarRE.QPBT + +open MIPStarRE.LDT hiding Measurement +open MIPStarRE.Quantum DistanceCalculus + +noncomputable section + +/-! ## The trivial bound -/ + +/-- A square-summable family of operators has total squared norm at most one on +a unit vector. -/ +theorem sum_norm_apply_sq_le_one {α ι : Type*} [Fintype α] [Fintype ι] +    [DecidableEq ι] (A : α → Op ι) (ψ : EuclideanSpace ℂ ι) (hψ : ‖ψ‖ = 1) +    (hA : ∑ a, (A a)ᴴ * A a ≤ 1) : +    ∑ a, ‖applyOperatorToState (A a) ψ‖ ^ 2 ≤ 1 := by +  have h := sum_norm_mul_apply_le A 1 ψ hA +  simp only [mul_one, WinImplications.applyOperatorToState_one, hψ] at h +  simpa using h + +/-- The state-dependent distance of two square-summable families is at most +`4` on a unit vector, under a uniform distribution. -/ +theorem opFamilyDistSq_uniform_le_four {X α ι : Type*} [Fintype X] [DecidableEq X] +    [Nonempty X] [Fintype α] [Fintype ι] [DecidableEq ι] +    (A B : X → α → Op ι) (ψ : EuclideanSpace ℂ ι) (hψ : ‖ψ‖ = 1) +    (hA : ∀ x, ∑ a, (A x a)ᴴ * A x a ≤ 1) (hB : ∀ x, ∑ a, (B x a)ᴴ * B x a ≤ 1) : +    opFamilyDistSq (uniformDistribution X) A B ψ ≤ 4 := by +  unfold opFamilyDistSq +  calc avgOver (uniformDistribution X) (fun x => +        ∑ a, ‖applyOperatorToState (A x a - B x a) ψ‖ ^ 2) +      ≤ avgOver (uniformDistribution X) (fun _ => (4 : ℝ)) := by +        refine avgOver_mono _ _ _ fun x => ?_ +        have hA' := sum_norm_apply_sq_le_one (A x) ψ hψ (hA x) +        have hB' := sum_norm_apply_sq_le_one (B x) ψ hψ (hB x) +        have hpt : ∀ a, ‖applyOperatorToState (A x a - B x a) ψ‖ ^ 2 ≤ +            2 * ‖applyOperatorToState (A x a) ψ‖ ^ 2 + +              2 * ‖applyOperatorToState (B x a) ψ‖ ^ 2 := by +          intro a +          have hsub : applyOperatorToState (A x a - B x a) ψ = +              applyOperatorToState (A x a) ψ - applyOperatorToState (B x a) ψ := by +            simp [applyOperatorToState] +          rw [hsub] +          have := norm_sub_le (applyOperatorToState (A x a) ψ) +            (applyOperatorToState (B x a) ψ) +          nlinarith [norm_nonneg (applyOperatorToState (A x a) ψ), +            norm_nonneg (applyOperatorToState (B x a) ψ), +            norm_nonneg (applyOperatorToState (A x a) ψ - +              applyOperatorToState (B x a) ψ), +            sq_nonneg (‖applyOperatorToState (A x a) ψ‖ - +              ‖applyOperatorToState (B x a) ψ‖)] +        calc ∑ a, ‖applyOperatorToState (A x a - B x a) ψ‖ ^ 2 +            ≤ ∑ a, (2 * ‖applyOperatorToState (A x a) ψ‖ ^ 2 + +                2 * ‖applyOperatorToState (B x a) ψ‖ ^ 2) := +              Finset.sum_le_sum fun a _ => hpt a +          _ = 2 * ∑ a, ‖applyOperatorToState (A x a) ψ‖ ^ 2 + +                2 * ∑ a, ‖applyOperatorToState (B x a) ψ‖ ^ 2 := by +              rw [Finset.sum_add_distrib, Finset.mul_sum, Finset.mul_sum] +          _ ≤ 4 := by linarith +    _ = 4 := avgOver_uniform_const _ + +/-- The effects of a projective measurement, placed on a register pair, are +square-summable to the identity. -/ +theorem ProjectiveSetting.sum_place_effect_conjTranspose_mul_self_le_one +    {P : AdmissibleParams} {ε : ℝ} (S : ProjectiveSetting P ε) (p : Placement) +    {α : Type*} [Fintype α] (M : Measurement α (S.ExpandedLocalSpace p.side)) +    (hM : MIPStarRE.QPBT.Measurement.IsProjective M) : +    ∑ a, (S.place p (M.effect a))ᴴ * S.place p (M.effect a) ≤ 1 := by +  refine le_of_eq ?_ +  calc ∑ a, (S.place p (M.effect a))ᴴ * S.place p (M.effect a) +      = ∑ a, S.place p (M.effect a) := by +        refine Finset.sum_congr rfl fun a _ => ?_ +        rw [← S.place_conjTranspose, ← S.place_mul, +          (hM a).isSelfAdjoint.isHermitian.eq, (hM a).isIdempotentElem.eq] +    _ = 1 := by rw [← S.place_finsetSum, M.sum_eq_one, S.place_one] + +/-- The products `A_a B_b` of the effects of two projective measurements on a +common space are square-summable to the identity. -/ +theorem sum_mul_conjTranspose_mul_self_eq_one {α β ι : Type*} [Fintype α] +    [Fintype β] [Fintype ι] [DecidableEq ι] +    (A : Measurement α ι) (B : Measurement β ι) +    (hA : MIPStarRE.QPBT.Measurement.IsProjective A) +    (hB : MIPStarRE.QPBT.Measurement.IsProjective B) : +    ∑ ab : α × β, (A.effect ab.1 * B.effect ab.2)ᴴ * (A.effect ab.1 * B.effect ab.2) = +      1 := by +  have hpt : ∀ (a : α) (b : β), +      (A.effect a * B.effect b)ᴴ * (A.effect a * B.effect b) = +        B.effect b * A.effect a * B.effect b := by +    intro a b +    rw [Matrix.conjTranspose_mul, (hA a).isSelfAdjoint.isHermitian.eq, +      (hB b).isSelfAdjoint.isHermitian.eq, Matrix.mul_assoc _ _ (A.effect a * B.effect b), +      ← Matrix.mul_assoc (A.effect a) (A.effect a), (hA a).isIdempotentElem.eq, +      ← Matrix.mul_assoc] +  rw [Fintype.sum_prod_type_right] +  calc ∑ b : β, ∑ a : α, (A.effect a * B.effect b)ᴴ * (A.effect a * B.effect b) +      = ∑ b : β, B.effect b * (∑ a : α, A.effect a) * B.effect b := by +        refine Finset.sum_congr rfl fun b _ => ?_ +        rw [Finset.mul_sum, Finset.sum_mul] +        exact Finset.sum_congr rfl fun a _ => hpt a b +    _ = 1 := by +        simp_rw [A.sum_eq_one, mul_one] +        rw [Finset.sum_congr rfl fun b _ => (hB b).isIdempotentElem.eq] +        exact B.sum_eq_one + +/-- The products `B_b A_a` of the effects of two projective measurements on a +common space, indexed by the pair `(a, b)`, are square-summable to the +identity. -/ +theorem sum_mul_conjTranspose_mul_self_eq_one' {α β ι : Type*} [Fintype α] +    [Fintype β] [Fintype ι] [DecidableEq ι] +    (A : Measurement α ι) (B : Measurement β ι) +    (hA : MIPStarRE.QPBT.Measurement.IsProjective A) +    (hB : MIPStarRE.QPBT.Measurement.IsProjective B) : +    ∑ ab : α × β, (B.effect ab.2 * A.effect ab.1)ᴴ * (B.effect ab.2 * A.effect ab.1) = +      1 := by +  have hpt : ∀ (a : α) (b : β), +      (B.effect b * A.effect a)ᴴ * (B.effect b * A.effect a) = +        A.effect a * B.effect b * A.effect a := by +    intro a b +    rw [Matrix.conjTranspose_mul, (hA a).isSelfAdjoint.isHermitian.eq, +      (hB b).isSelfAdjoint.isHermitian.eq, Matrix.mul_assoc _ _ (B.effect b * A.effect a), +      ← Matrix.mul_assoc (B.effect b) (B.effect b), (hB b).isIdempotentElem.eq, +      ← Matrix.mul_assoc] +  rw [Fintype.sum_prod_type] +  calc ∑ a : α, ∑ b : β, (B.effect b * A.effect a)ᴴ * (B.effect b * A.effect a) +      = ∑ a : α, A.effect a * (∑ b : β, B.effect b) * A.effect a := by +        refine Finset.sum_congr rfl fun a _ => ?_ +        rw [Finset.mul_sum, Finset.sum_mul] +        exact Finset.sum_congr rfl fun b _ => hpt a b +    _ = 1 := by +        simp_rw [B.sum_eq_one, mul_one] +        rw [Finset.sum_congr rfl fun a _ => (hA a).isIdempotentElem.eq] +        exact A.sum_eq_one + +/-! ## The chain of closeness estimates -/ + +namespace ProjectiveSetting + +variable {P : AdmissibleParams} {ε : ℝ} + +/-- The three closeness conclusions of `lem:qld-4-10` for a pair of projective +families close to the placed sandwiches: with `η` the closeness of `Q` to `R` +on every placement, `C₁ √ε` the closeness of `R` to the ordered product, +`C₂ √ε` the commutation error, and `C₃ ε` the cross-placement consistency of +the ordered products, the distances from `Q` on one placement to the two +ordered products and to `Q` on the opposite placement are bounded by explicit +combinations.  Paper +`references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:838-881`. -/ +theorem chain_bounds (S : ProjectiveSetting P ε) +    (Q : (side : PlayerSide) → PointPair P → +      Measurement (PauliScalar P × PauliScalar P) (S.ExpandedLocalSpace side)) +    (η C₁ C₂ C₃ : ℝ) +    (hQR : ∀ p : Placement, opFamilyDistSq (uniformDistribution (PointPair P)) +      (fun xz (ab : PauliScalar P × PauliScalar P) => +        S.place p ((Q p.side xz).effect ab)) +      (fun xz ab => S.place p ((S.sandwichPoint p.side xz.1 xz.2).effect ab)) +      S.psiHat ≤ η) +    (h₁ : ∀ p : Placement, opFamilyDistSq (uniformDistribution (PointPair P)) +      (fun xz (ab : PauliScalar P × PauliScalar P) => +        S.place p ((S.sandwichPoint p.side xz.1 xz.2).effect ab)) +      (fun xz ab => S.place p +        ((S.pointMeasExp p.side .Z xz.2).effect ab.2 * +          (S.pointMeasExp p.side .X xz.1).effect ab.1)) +      S.psiHat ≤ C₁ * Real.sqrt ε) +    (h₂ : ∀ p : Placement, opFamilyDistSq (uniformDistribution (PointPair P)) +      (fun xz (ab : PauliScalar P × PauliScalar P) => S.place p +        ((S.pointMeasExp p.side .X xz.1).effect ab.1 * +          (S.pointMeasExp p.side .Z xz.2).effect ab.2)) +      (fun xz ab => S.place p +        ((S.pointMeasExp p.side .Z xz.2).effect ab.2 * +          (S.pointMeasExp p.side .X xz.1).effect ab.1)) +      S.psiHat ≤ C₂ * Real.sqrt ε) +    (h₃ : ∀ p₁ p₂ : Placement, p₁.IsOpposite p₂ → +      opFamilyDistSq (uniformDistribution (PointPair P)) +        (fun xz (ab : PauliScalar P × PauliScalar P) => S.place p₁ +          ((S.pointMeasExp p₁.side .Z xz.2).effect ab.2 * +            (S.pointMeasExp p₁.side .X xz.1).effect ab.1)) +        (fun xz ab => S.place p₂ +          ((S.pointMeasExp p₂.side .X xz.1).effect ab.1 * +            (S.pointMeasExp p₂.side .Z xz.2).effect ab.2)) +        S.psiHat ≤ C₃ * ε) +    (p₁ p₂ : Placement) (hopp : p₁.IsOpposite p₂) : +    opFamilyDistSq (uniformDistribution (PointPair P)) +        (fun xz (ab : PauliScalar P × PauliScalar P) => +          S.place p₁ ((Q p₁.side xz).effect ab)) +        (fun xz ab => S.place p₂ +          ((S.pointMeasExp p₂.side .X xz.1).effect ab.1 * +            (S.pointMeasExp p₂.side .Z xz.2).effect ab.2)) +        S.psiHat ≤ 2 * η + 4 * (C₁ * Real.sqrt ε) + 4 * (C₃ * ε) ∧ +      opFamilyDistSq (uniformDistribution (PointPair P)) +        (fun xz (ab : PauliScalar P × PauliScalar P) => +          S.place p₁ ((Q p₁.side xz).effect ab)) +        (fun xz ab => S.place p₂ +          ((S.pointMeasExp p₂.side .Z xz.2).effect ab.2 * +            (S.pointMeasExp p₂.side .X xz.1).effect ab.1)) +        S.psiHat ≤ 4 * η + 8 * (C₁ * Real.sqrt ε) + 8 * (C₃ * ε) + +          2 * (C₂ * Real.sqrt ε) ∧ +      opFamilyDistSq (uniformDistribution (PointPair P)) +        (fun xz (ab : PauliScalar P × PauliScalar P) => +          S.place p₁ ((Q p₁.side xz).effect ab)) +        (fun xz ab => S.place p₂ ((Q p₂.side xz).effect ab)) +        S.psiHat ≤ 12 * η + 20 * (C₁ * Real.sqrt ε) + 16 * (C₃ * ε) + +          4 * (C₂ * Real.sqrt ε) := by +  -- `R_1 ≈ M^X M^Z` on the opposite placement +  have hRXZ := opFamilyDistSq_le_of_le_of_le (uniformDistribution (PointPair P)) +    _ _ _ S.psiHat _ _ (h₁ p₁) (h₃ p₁ p₂ hopp) +  -- `Q_1 ≈ M^X M^Z` on the opposite placement +  have hQXZ := opFamilyDistSq_le_of_le_of_le (uniformDistribution (PointPair P)) +    _ _ _ S.psiHat _ _ (hQR p₁) hRXZ +  -- `Q_1 ≈ M^Z M^X` on the opposite placement +  have hQZX := opFamilyDistSq_le_of_le_of_le (uniformDistribution (PointPair P)) +    _ _ _ S.psiHat _ _ hQXZ (h₂ p₂) +  -- `M^Z M^X ≈ Q_2` on the opposite placement +  have hZXQ : opFamilyDistSq (uniformDistribution (PointPair P)) +      (fun xz (ab : PauliScalar P × PauliScalar P) => S.place p₂ +        ((S.pointMeasExp p₂.side .Z xz.2).effect ab.2 * +          (S.pointMeasExp p₂.side .X xz.1).effect ab.1)) +      (fun xz ab => S.place p₂ ((Q p₂.side xz).effect ab)) +      S.psiHat ≤ 2 * η + 2 * (C₁ * Real.sqrt ε) := by +    rw [opFamilyDistSq_symm] +    exact opFamilyDistSq_le_of_le_of_le (uniformDistribution (PointPair P)) +      _ _ _ S.psiHat _ _ (hQR p₂) (h₁ p₂) +  have hQQ := opFamilyDistSq_le_of_le_of_le (uniformDistribution (PointPair P)) +    _ _ _ S.psiHat _ _ hQZX hZXQ +  refine ⟨by linarith, by linarith, by linarith⟩ + +end ProjectiveSetting + +/-! ## Collapsing the error terms into one power -/ + +/-- For `0 ≤ ε ≤ 1`, the error terms `ε`, `√ε`, and `(C₀ (ε + √ε))^{1/4}` +with `C₀ ≥ 1` are all bounded by multiples of `ε^{1/8}`. -/ +theorem error_terms_le_rpow_eighth {ε C₀ : ℝ} (hε : 0 ≤ ε) (hε1 : ε ≤ 1) +    (hC₀ : 1 ≤ C₀) : +    ε ≤ Real.rpow ε (1 / 8 : ℝ) ∧ Real.sqrt ε ≤ Real.rpow ε (1 / 8 : ℝ) ∧ +      Real.rpow (C₀ * (ε + Real.sqrt ε)) (1 / 4 : ℝ) ≤ +        2 * C₀ * Real.rpow ε (1 / 8 : ℝ) := by +  rcases eq_or_lt_of_le hε with h0 | hpos +  · subst h0 +    have h8 : Real.rpow (0 : ℝ) (1 / 8 : ℝ) = 0 := Real.zero_rpow (by norm_num) +    have h4 : Real.rpow (C₀ * (0 + Real.sqrt 0)) (1 / 4 : ℝ) = 0 := by +      rw [Real.sqrt_zero, add_zero, mul_zero] +      exact Real.zero_rpow (by norm_num) +    rw [h8, h4, Real.sqrt_zero] +    refine ⟨le_rfl, le_rfl, ?_⟩ +    positivity +  · have hsqrt : Real.sqrt ε = Real.rpow ε (1 / 2 : ℝ) := Real.sqrt_eq_rpow ε +    have hε1' : Real.rpow ε 1 = ε := Real.rpow_one ε +    have hmono : ∀ y z : ℝ, z ≤ y → Real.rpow ε y ≤ Real.rpow ε z := fun y z hyz => +      Real.rpow_le_rpow_of_exponent_ge hpos hε1 hyz +    refine ⟨?_, ?_, ?_⟩ +    · exact le_of_eq_of_le hε1'.symm (hmono 1 (1 / 8) (by norm_num)) +    · rw [hsqrt] +      exact hmono (1 / 2) (1 / 8) (by norm_num) +    · have hsum : ε + Real.sqrt ε ≤ 2 * Real.sqrt ε := by +        have : ε ≤ Real.sqrt ε := by +          rw [hsqrt] +          exact le_of_eq_of_le hε1'.symm (hmono 1 (1 / 2) (by norm_num)) +        linarith +      have hC : 0 ≤ 2 * C₀ := by linarith +      calc Real.rpow (C₀ * (ε + Real.sqrt ε)) (1 / 4 : ℝ) +          ≤ Real.rpow (2 * C₀ * Real.sqrt ε) (1 / 4 : ℝ) := by +            apply Real.rpow_le_rpow (by positivity) _ (by norm_num) +            nlinarith [Real.sqrt_nonneg ε] +        _ = Real.rpow (2 * C₀) (1 / 4 : ℝ) * Real.rpow ε (1 / 8 : ℝ) := by +            change (2 * C₀ * Real.sqrt ε) ^ (1 / 4 : ℝ) = +              (2 * C₀) ^ (1 / 4 : ℝ) * ε ^ (1 / 8 : ℝ) +            rw [Real.mul_rpow hC (Real.sqrt_nonneg ε), Real.sqrt_eq_rpow, +              ← Real.rpow_mul hε] +            norm_num +        _ ≤ 2 * C₀ * Real.rpow ε (1 / 8 : ℝ) := by +            refine mul_le_mul_of_nonneg_right ?_ (Real.rpow_nonneg hε _) +            calc Real.rpow (2 * C₀) (1 / 4 : ℝ) ≤ Real.rpow (2 * C₀) 1 := +                  Real.rpow_le_rpow_of_exponent_le (by linarith) (by norm_num) +              _ = 2 * C₀ := Real.rpow_one _ + +end + +end MIPStarRE.QPBT diff --git a/MIPStarRE/QPBT/Combining/Points/Commutation.lean b/MIPStarRE/QPBT/Combining/Points/Commutation.lean new file mode 100644 index 00000000..29de3421 --- /dev/null +++ b/MIPStarRE/QPBT/Combining/Points/Commutation.lean @@ -0,0 +1,457 @@ +import MIPStarRE.QPBT.Combining.Points.Placement + +/-! +# Approximate commutation of the field-valued expanded point measurements + +The approximate commutation of `lem:qld-comm-cons` is stated for the binary +refinements `M^{(Point,W),u,r}_b` of the expanded point measurements.  The +combined point measurements of `lem:qld-4-10` are built here directly from the +`F_q`-valued measurements `M^{(Point,W),u}_a`, so the commutation estimate is +transferred to them.  The transfer is exact: since +`M^{(Point,X),x}_a = E_r (-1)^{tr(ar)} X^r(x)` and +`M^{(Point,Z),z}_b = E_s (-1)^{tr(bs)} Z^s(z)`, the commutator of the two +measurement effects is the Fourier transform, in the outcome pair `(a, b)`, +of the commutators of the expanded observables, and Parseval's identity for +the additive characters of `F_q` turns the sum over `(a, b)` of the squared +norms into the average over `(r, s)` of the squared norms of the observable +commutators.  No factor depending on `q` is lost. + +## Main results + +* `sum_norm_sum_smul_sq_of_orthogonal`: Parseval's identity for an orthogonal +  system of coefficients. +* `sum_fixedCharacter_mul`: Fourier cancellation for the fixed trace character. +* `expPoint_comm`: the field-valued expanded point measurements approximately +  commute on every register placement, with the error of +  `lem:qld-comm-cons`. + +## References + +The commutation estimate for the binary refinements is item 2 of +`lem:qld-comm-cons`, blueprint +`blueprint/src/chapter/ch14_qpbt_observables.tex:1139-1210`, paper +`references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:466-505`; the +Fourier form of the point effects is `def:expanded-point-measurement`, paper +lines 384--418.  The role of the transfer in the proof of `lem:qld-4-10` is +explained in `docs/paper-gaps/qpbt_linearity-theorem-quotation.tex`. +-/ + +open scoped BigOperators Matrix MatrixOrder ComplexOrder + +namespace MIPStarRE.QPBT + +open MIPStarRE.LDT hiding Measurement +open MIPStarRE.Quantum +open MIPStarRE.LDT.Preliminaries + +noncomputable section + +/-- A pair of points, one for the `X` basis and one for the `Z` basis.  This +is the question pair `(x, z)` of `lem:qld-4-10`, paper +`references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:689-709`. -/ +abbrev PointPair (P : AdmissibleParams) := +  (Fin P.m → PauliScalar P) × (Fin P.m → PauliScalar P) + +/-! ## Parseval's identity for an orthogonal system of coefficients -/ + +/-- Formalization-only auxiliary for `lem:qld-4-10`: if the coefficient +vectors `i ↦ c j i`, `j` ranging over a finite set, are orthogonal with common +squared norm `N`, then the squared norms of the weighted sums +`∑ i, c j i • v i` add up to `N` times the squared norms of the `v i`. -/ +theorem sum_norm_sum_smul_sq_of_orthogonal {I J E : Type*} [Fintype I] +    [DecidableEq I] [Fintype J] [NormedAddCommGroup E] [InnerProductSpace ℂ E] +    (c : J → I → ℂ) (N : ℝ) +    (horth : ∀ i i', ∑ j, (starRingEnd ℂ) (c j i) * c j i' = +      if i = i' then (N : ℂ) else 0) +    (v : I → E) : +    ∑ j, ‖∑ i, c j i • v i‖ ^ 2 = N * ∑ i, ‖v i‖ ^ 2 := by +  have hnorm : ∀ x : E, ‖x‖ ^ 2 = (inner ℂ x x).re := fun x => by +    simpa using (inner_self_eq_norm_sq (𝕜 := ℂ) x).symm +  have hj : ∀ j, ‖∑ i, c j i • v i‖ ^ 2 = +      (∑ i, ∑ i', ((starRingEnd ℂ) (c j i) * c j i') * +        inner ℂ (v i) (v i')).re := by +    intro j +    rw [hnorm, sum_inner] +    simp only [inner_sum, inner_smul_left, inner_smul_right] +    congr 1 +    refine Finset.sum_congr rfl fun i _ => Finset.sum_congr rfl fun i' _ => ?_ +    ring +  have hsum : ∑ j, ∑ i, ∑ i', ((starRingEnd ℂ) (c j i) * c j i') * +      inner ℂ (v i) (v i') = ∑ i, (N : ℂ) * inner ℂ (v i) (v i) := by +    rw [Finset.sum_comm] +    refine Finset.sum_congr rfl fun i _ => ?_ +    rw [Finset.sum_comm] +    calc ∑ i', ∑ j, ((starRingEnd ℂ) (c j i) * c j i') * inner ℂ (v i) (v i') +        = ∑ i', (∑ j, (starRingEnd ℂ) (c j i) * c j i') * +            inner ℂ (v i) (v i') := by +          refine Finset.sum_congr rfl fun i' _ => ?_ +          rw [Finset.sum_mul] +      _ = ∑ i', (if i = i' then (N : ℂ) else 0) * inner ℂ (v i) (v i') := by +          refine Finset.sum_congr rfl fun i' _ => ?_ +          rw [horth] +      _ = (N : ℂ) * inner ℂ (v i) (v i) := by +          simp [ite_mul] +  calc ∑ j, ‖∑ i, c j i • v i‖ ^ 2 +      = (∑ j, ∑ i, ∑ i', ((starRingEnd ℂ) (c j i) * c j i') * +          inner ℂ (v i) (v i')).re := by +        rw [Complex.re_sum] +        exact Finset.sum_congr rfl fun j _ => hj j +    _ = (∑ i, (N : ℂ) * inner ℂ (v i) (v i)).re := by rw [hsum] +    _ = N * ∑ i, ‖v i‖ ^ 2 := by +        rw [Complex.re_sum, Finset.mul_sum] +        refine Finset.sum_congr rfl fun i _ => ?_ +        rw [Complex.re_ofReal_mul, ← hnorm] + +/-! ## The fixed trace character -/ + +section Characters + +variable {P : AdmissibleParams} + +/-- The phase induced by the fixed binary trace is an additive character. +Paper `references/qpbt-paper/04_preliminaries.tex:1052-1081`. -/ +theorem fixedCharacter_mul (x y : PauliScalar P) : +    phaseSign (fixedBinTrace P.model x) * phaseSign (fixedBinTrace P.model y) = +      phaseSign (fixedBinTrace P.model (x + y)) := by +  rw [fixedBinTrace, map_add, phaseSign_eq_ffChar, phaseSign_eq_ffChar, +    phaseSign_eq_ffChar] +  exact ((ZMod.stdAddChar (N := 2)).map_add_eq_mul _ _).symm + +/-- The fixed trace character is even: negation acts trivially on the binary +trace. -/ +theorem fixedCharacter_neg (x : PauliScalar P) : +    phaseSign (fixedBinTrace P.model (-x)) = +      phaseSign (fixedBinTrace P.model x) := by +  rw [fixedBinTrace, map_neg, ZMod.neg_eq_self_mod_two] + +/-- Fourier cancellation for the fixed trace character: the character sums to +the field size at `0` and to zero elsewhere.  This is `lem:cancellation` for +the one-dimensional space, blueprint +`blueprint/src/chapter/ch11_qpbt_algebra.tex:686`, paper +`references/qpbt-paper/04_preliminaries.tex:1124-1132`. -/ +theorem sum_fixedCharacter_mul (c : PauliScalar P) : +    ∑ a : PauliScalar P, phaseSign (fixedBinTrace P.model (a * c)) = +      if c = 0 then (Fintype.card (PauliScalar P) : ℂ) else 0 := by +  have h : (𝔼 r : PauliScalar P, phaseSign (fixedBinTrace P.model (r * c))) = +      if c = 0 then (1 : ℂ) else 0 := by +    simpa only [fixedBinTrace, phaseSign_eq_ffChar, +      MIPStarRE.LDT.Preliminaries.ffChar_apply] using +      (fourier_fact_scalar (p := 2) (F := PauliScalar P) c) +  rw [Finset.expect_eq_sum_div_card] at h +  have hcard : (Fintype.card (PauliScalar P) : ℂ) ≠ 0 := +    Nat.cast_ne_zero.mpr Fintype.card_ne_zero +  rw [Finset.card_univ, div_eq_iff hcard] at h +  rw [h] +  split_ifs <;> simp + +/-- Orthogonality of two fixed trace characters. -/ +theorem sum_fixedCharacter_mul_fixedCharacter (r r' : PauliScalar P) : +    ∑ a : PauliScalar P, phaseSign (fixedBinTrace P.model (a * r)) * +        phaseSign (fixedBinTrace P.model (a * r')) = +      if r = r' then (Fintype.card (PauliScalar P) : ℂ) else 0 := by +  have hterm : ∀ a : PauliScalar P, +      phaseSign (fixedBinTrace P.model (a * r)) * +          phaseSign (fixedBinTrace P.model (a * r')) = +        phaseSign (fixedBinTrace P.model (a * (r' - r))) := by +    intro a +    rw [← fixedCharacter_neg (a * r), fixedCharacter_mul] +    congr 2 +    ring +  simp_rw [hterm, sum_fixedCharacter_mul] +  by_cases h : r = r' +  · simp [h] +  · rw [if_neg h, if_neg] +    intro h' +    exact h (sub_eq_zero.mp h').symm + +/-- The two-dimensional character system `(a, b) ↦ χ(a r) χ(b s)` is orthogonal +with common squared norm `q ^ 2`. -/ +theorem sum_pairCharacter_mul_pairCharacter +    (rs rs' : PauliScalar P × PauliScalar P) : +    ∑ ab : PauliScalar P × PauliScalar P, +        (starRingEnd ℂ) (phaseSign (fixedBinTrace P.model (ab.1 * rs.1)) * +            phaseSign (fixedBinTrace P.model (ab.2 * rs.2))) * +          (phaseSign (fixedBinTrace P.model (ab.1 * rs'.1)) * +            phaseSign (fixedBinTrace P.model (ab.2 * rs'.2))) = +      if rs = rs' then +        (((Fintype.card (PauliScalar P) : ℝ) ^ 2 : ℝ) : ℂ) else 0 := by +  have hstar : ∀ t : ZMod 2, (starRingEnd ℂ) (phaseSign t) = phaseSign t := by +    intro t +    rw [← Complex.star_def] +    exact star_phaseSign t +  simp_rw [map_mul, hstar] +  rw [Fintype.sum_prod_type] +  calc ∑ a : PauliScalar P, ∑ b : PauliScalar P, +        phaseSign (fixedBinTrace P.model (a * rs.1)) * +            phaseSign (fixedBinTrace P.model (b * rs.2)) * +          (phaseSign (fixedBinTrace P.model (a * rs'.1)) * +            phaseSign (fixedBinTrace P.model (b * rs'.2))) +      = (∑ a : PauliScalar P, phaseSign (fixedBinTrace P.model (a * rs.1)) * +            phaseSign (fixedBinTrace P.model (a * rs'.1))) * +          ∑ b : PauliScalar P, phaseSign (fixedBinTrace P.model (b * rs.2)) * +            phaseSign (fixedBinTrace P.model (b * rs'.2)) := by +        rw [Finset.sum_mul_sum] +        refine Finset.sum_congr rfl fun a _ => Finset.sum_congr rfl fun b _ => ?_ +        ring +    _ = _ := by +        rw [sum_fixedCharacter_mul_fixedCharacter, +          sum_fixedCharacter_mul_fixedCharacter] +        by_cases h1 : rs.1 = rs'.1 <;> by_cases h2 : rs.2 = rs'.2 +        · rw [if_pos h1, if_pos h2, if_pos (Prod.ext h1 h2)] +          push_cast +          ring +        · rw [if_pos h1, if_neg h2, if_neg (fun h => h2 (congrArg Prod.snd h))] +          simp +        · rw [if_neg h1, if_pos h2, if_neg (fun h => h1 (congrArg Prod.fst h))] +          simp +        · rw [if_neg h1, if_neg h2, if_neg (fun h => h1 (congrArg Prod.fst h))] +          simp + +end Characters + +/-! ## Fourier form of the point effects and of their commutator -/ + +/-- A uniform operator average is the normalized sum. -/ +theorem averageOperatorOverDistribution_uniform_eq_inv_card_smul_sum +    {α ι : Type*} [Fintype α] [DecidableEq α] [Nonempty α] +    [Fintype ι] [DecidableEq ι] (f : α → Op