ℂ) (X Z : K → Op ι) : +    (c • ∑ s, β s • Z s) * (c • ∑ r, α r • X r) = +      (c * c) • ∑ rs : K × K, (α rs.1 * β rs.2) • (Z rs.2 * X rs.1) := by +  rw [Fintype.sum_prod_type_right, smul_mul_smul_comm, Finset.sum_mul_sum] +  congr 1 +  refine Finset.sum_congr rfl fun s _ => Finset.sum_congr rfl fun r _ => ?_ +  rw [smul_mul_smul_comm, mul_comm (β s)] + +/-- The commutator of two field-valued point effects is the Fourier transform +of the commutators of the expanded observables. -/ +theorem expPointOp_commutator_eq (S : ProjectiveSetting P ε) (side : PlayerSide) +    (x z : Fin P.m → PauliScalar P) (a b : PauliScalar P) : +    S.expPointOp side .X x a * S.expPointOp side .Z z b - +        S.expPointOp side .Z z b * S.expPointOp side .X x a = +      ((Fintype.card (PauliScalar P) : ℂ)⁻¹ * +          (Fintype.card (PauliScalar P) : ℂ)⁻¹) • +        ∑ rs : PauliScalar P × PauliScalar P, +          (phaseSign (fixedBinTrace P.model (a * rs.1)) * +              phaseSign (fixedBinTrace P.model (b * rs.2))) • +            (S.expObs side .X rs.1 x * S.expObs side .Z rs.2 z - +              S.expObs side .Z rs.2 z * S.expObs side .X rs.1 x) := by +  rw [expPointOp_eq_inv_card_smul_sum, expPointOp_eq_inv_card_smul_sum, +    smul_sum_mul_smul_sum, smul_sum_mul_smul_sum_swap, ← smul_sub, +    ← Finset.sum_sub_distrib] +  congr 1 +  refine Finset.sum_congr rfl fun rs _ => ?_ +  rw [smul_sub] + +/-- Formalization-only auxiliary: an operator applied to a state is linear in +the operator over finite sums. -/ +theorem applyOperatorToState_finsetSum {ι γ : Type*} [Fintype ι] [DecidableEq ι] +    (s : Finset γ) (M : γ → Op ι) (ψ : EuclideanSpace ℂ ι) : +    applyOperatorToState (∑ x ∈ s, M x) ψ = +      ∑ x ∈ s, applyOperatorToState (M x) ψ := by +  unfold applyOperatorToState +  simp only [map_sum, LinearMap.sum_apply] + +/-- Parseval transfer, pointwise in the point pair: the summed squared norms of +the placed commutators of the field-valued point effects equal the average over +`(r, s)` of the squared norms of the placed commutators of the expanded +observables. -/ +theorem sum_norm_place_expPointOp_commutator_sq (S : ProjectiveSetting P ε) +    (p : Placement) (x z : Fin P.m → PauliScalar P) : +    ∑ ab : PauliScalar P × PauliScalar P, +        ‖applyOperatorToState (S.place p +          (S.expPointOp p.side .X x ab.1 * S.expPointOp p.side .Z z ab.2 - +            S.expPointOp p.side .Z z ab.2 * S.expPointOp p.side .X x ab.1)) +          S.psiHat‖ ^ 2 = +      avgOver (uniformDistribution (PauliScalar P × PauliScalar P)) +        (fun rs => ‖applyOperatorToState (S.place p +          (S.expObs p.side .X rs.1 x * S.expObs p.side .Z rs.2 z - +            S.expObs p.side .Z rs.2 z * S.expObs p.side .X rs.1 x)) +          S.psiHat‖ ^ 2) := by +  set v : PauliScalar P × PauliScalar P → +      EuclideanSpace ℂ (SixReg P S.toStrategy.ιA S.toStrategy.ιB) := +    fun rs => applyOperatorToState (S.place p +      (S.expObs p.side .X rs.1 x * S.expObs p.side .Z rs.2 z - +        S.expObs p.side .Z rs.2 z * S.expObs p.side .X rs.1 x)) S.psiHat +  set c : ℂ := (Fintype.card (PauliScalar P) : ℂ)⁻¹ +  have hpt : ∀ ab : PauliScalar P × PauliScalar P, +      applyOperatorToState (S.place p +          (S.expPointOp p.side .X x ab.1 * S.expPointOp p.side .Z z ab.2 - +            S.expPointOp p.side .Z z ab.2 * S.expPointOp p.side .X x ab.1)) +          S.psiHat = +        (c * c) • ∑ rs : PauliScalar P × PauliScalar P, +          (phaseSign (fixedBinTrace P.model (ab.1 * rs.1)) * +              phaseSign (fixedBinTrace P.model (ab.2 * rs.2))) • v rs := by +    intro ab +    rw [expPointOp_commutator_eq, place_smul, place_finsetSum, +      WinImplications.applyOperatorToState_smul_op, applyOperatorToState_finsetSum] +    congr 1 +    refine Finset.sum_congr rfl fun rs _ => ?_ +    rw [place_smul, WinImplications.applyOperatorToState_smul_op] +  have hparseval := sum_norm_sum_smul_sq_of_orthogonal +    (fun (ab rs : PauliScalar P × PauliScalar P) => +      phaseSign (fixedBinTrace P.model (ab.1 * rs.1)) * +        phaseSign (fixedBinTrace P.model (ab.2 * rs.2))) +    ((Fintype.card (PauliScalar P) : ℝ) ^ 2) +    (fun rs rs' => sum_pairCharacter_mul_pairCharacter rs rs') v +  have hq : (0 : ℝ) < (Fintype.card (PauliScalar P) : ℝ) := by +    exact_mod_cast Fintype.card_pos +  have hcnorm : ‖c * c‖ = ((Fintype.card (PauliScalar P) : ℝ) ^ 2)⁻¹ := by +    simp only [c, norm_mul, norm_inv, Complex.norm_natCast] +    rw [sq, mul_inv] +  calc ∑ ab : PauliScalar P × PauliScalar P, +        ‖applyOperatorToState (S.place p +          (S.expPointOp p.side .X x ab.1 * S.expPointOp p.side .Z z ab.2 - +            S.expPointOp p.side .Z z ab.2 * S.expPointOp p.side .X x ab.1)) +          S.psiHat‖ ^ 2 +      = ∑ ab : PauliScalar P × PauliScalar P, +          ‖c * c‖ ^ 2 * ‖∑ rs : PauliScalar P × PauliScalar P, +            (phaseSign (fixedBinTrace P.model (ab.1 * rs.1)) * +              phaseSign (fixedBinTrace P.model (ab.2 * rs.2))) • v rs‖ ^ 2 := by +        refine Finset.sum_congr rfl fun ab _ => ?_ +        rw [hpt, norm_smul, mul_pow] +    _ = ‖c * c‖ ^ 2 * (((Fintype.card (PauliScalar P) : ℝ) ^ 2) * +          ∑ rs, ‖v rs‖ ^ 2) := by +        rw [← Finset.mul_sum, hparseval] +    _ = avgOver (uniformDistribution (PauliScalar P × PauliScalar P)) +          (fun rs => ‖v rs‖ ^ 2) := by +        rw [avgOver_uniform_eq_inv_card_mul_sum, Fintype.card_prod, hcnorm] +        push_cast +        field_simp + +/-- The field-valued expanded point measurements approximately commute on each +of the four register placements, with the error of item 2 of +`lem:qld-comm-cons`.  The estimate is transferred from the binary refinements +of the source by the Parseval identity, without loss in the field size.  Paper +`references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:466-505`, +blueprint `blueprint/src/chapter/ch14_qpbt_observables.tex:1139-1210`; the +role of this form in the proof of `lem:qld-4-10` is explained in +`docs/paper-gaps/qp