eStrategySide p.side (S.twistedCommutator p.side ω)) +          S.toStrategy.ψ‖ ^ 2) := by +    unfold opFamilyDistSq +    calc avgOver (uniformDistribution (PointPair P)) (fun xz => +          ∑ ab : PauliScalar P × PauliScalar P, +            ‖applyOperatorToState (S.place p +                ((S.pointMeasExp p.side .X xz.1).effect ab.1 * +                  (S.pointMeasExp p.side .Z xz.2).effect ab.2) - +              S.place p ((S.pointMeasExp p.side .Z xz.2).effect ab.2 * +                (S.pointMeasExp p.side .X xz.1).effect ab.1)) S.psiHat‖ ^ 2) +        = avgOver (uniformDistribution (PointPair P)) (fun xz => +            avgOver (uniformDistribution (PauliScalar P × PauliScalar P)) +              (fun rs => ‖applyOperatorToState +                (S.placeStrategySide p.side +                  (S.twistedCommutator p.side (xz.1, xz.2, rs.1, rs.2))) +                S.toStrategy.ψ‖ ^ 2)) := by +          refine avgOver_congr _ _ _ fun xz => ?_ +          rw [← avgOver_congr _ _ _ (hnorm xz.1 xz.2), +            ← sum_norm_place_expPointOp_commutator_sq S p xz.1 xz.2] +          refine Finset.sum_congr rfl fun ab _ => ?_ +          rw [place_sub] +          rfl +      _ = avgOver (uniformDistribution (PointPair P × (PauliScalar P × PauliScalar P))) +            (fun q => ‖applyOperatorToState +              (S.placeStrategySide p.side +                (S.twistedCommutator p.side (q.1.1, q.1.2, q.2.1, q.2.2))) +              S.toStrategy.ψ‖ ^ 2) := +          (avgOver_uniform_prod (fun (xz : PointPair P) +            (rs : PauliScalar P × PauliScalar P) => ‖applyOperatorToState +              (S.placeStrategySide p.side +                (S.twistedCommutator p.side (xz.1, xz.2, rs.1, rs.2))) +              S.toStrategy.ψ‖ ^ 2)).symm +      _ = avgOver (uniformDistribution (PauliTuple P)) (fun ω => +            ‖applyOperatorToState +              (S.placeStrategySide p.side (S.twistedCommutator p.side ω)) +              S.toStrategy.ψ‖ ^ 2) := by +          rw [avg