nePoint_defect_le +    {P : AdmissibleParams} {ε δQ : ℝ} {S : ProjectiveSetting P ε} +    (points : CombinedPointsWitness S δQ) +    (p1 p2 : Placement) (hopp : p1.IsOpposite p2) : +    consistencyDefect (Distribution.prod (linePointDist P.toLdParams) +      (linePointDist P.toLdParams)) +      (fun sample ab => +        S.place p1 ((points.Q p1.side sample.1.2 sample.2.2).effect ab)) +      (fun sample ab => +        S.place p2 ((points.Q p2.side sample.1.2 sample.2.2).effect ab)) +      S.psiHat ≤ δQ := by +  classical +  have htransport := avgOver_prod_linePointDist_points P.toLdParams (fun xz => +    ∑ ab, ∑ cd, if ab = cd then 0 else +      (inner ℂ S.psiHat ((EuclideanSpace.equiv _ ℂ).symm +        ((S.place p1 ((points.Q p1.side xz.1 xz.2).effect ab) * +          S.place p2 ((points.Q p2.side xz.1 xz.2).effect cd)) *ᵥ S.psiHat.ofLp))).re) +  unfold consistencyDefect +  rw [htransport] +  exact points.self_consistency_defect_le p1 p2 hopp + +end + +end MIPStarRE.QPBT diff --git a/MIPStarRE/QPBT/Combining/Lines/SamePlacementDistance.lean b/MIPStarRE/QPBT/Combining/Lines/SamePlacementDistance.lean new file mode 100644 index 00000000..b9c6f882 --- /dev/null +++ b/MIPStarRE/QPBT/Combining/Lines/SamePlacementDistance.lean @@ -0,0 +1,69 @@ +import MIPStarRE.QPBT.Combining.Lines.OptionPostprocessDistance +import MIPStarRE.QPBT.Combining.Lines.PointSelfConsistency +import MIPStarRE.QPBT.Observables.LineMeasurement + +/-! +# Same-placement line-point distance + +This module compares an evaluated expanded-line measurement with the completed +expanded-point measurement on the same placement. The proof passes through the +opposite placement, using line-point consistency and point self-consistency. + +## References + +This is the intermediate comparison in `eq:pasting-q1`, +`references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:936-941`. +-/ + +open scoped BigOperators + +namespace MIPStarRE.QPBT + +open MIPStarRE.LDT hiding Measurement +open MIPStarRE.Quantum + +n