aLine ε := Real.sqrt_nonneg ε +  nlinarith + +end + +end MIPStarRE.QPBT diff --git a/MIPStarRE/QPBT/Combining/Points.lean b/MIPStarRE/QPBT/Combining/Points.lean index ee1d8bbd..280cac0b 100644 --- a/MIPStarRE/QPBT/Combining/Points.lean +++ b/MIPStarRE/QPBT/Combining/Points.lean @@ -1,3 +1,4 @@ +import MIPStarRE.QPBT.Combining.Points.Closeness  import MIPStarRE.QPBT.Combining.PointsDataProcessing    /-! @@ -17,7 +18,7 @@ The coarse-graining is `lem:qld-4-12` in the same blueprint, with paper source  `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:993-1011`.  -/   -open scoped BigOperators +open scoped BigOperators Matrix MatrixOrder ComplexOrder    namespace MIPStarRE.QPBT   @@ -44,16 +45,200 @@ noncomputable def extendedQ {P : AdmissibleParams} {ε δ : ℝ}      Measurement (PauliScalar P) (S.ExpandedLocalSpace side) :=    (points.Q side x z).postprocess fun ab => alpha * ab.1 + beta * ab.2   +/-- The first postprocessed joint-point effect is its X marginal sum. +This formalization-only identity is the definition preceding +`eq:qld-qxz-close-to-point`, paper +`references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:917-932`. -/ +theorem postprocess_fst_effect {P : AdmissibleParams} {ε δQ : ℝ} +    {S : ProjectiveSetting P ε} (points : CombinedPointsWitness S δQ) +    (side : PlayerSide) (x z : Fin P.m -> PauliScalar P) (a : PauliScalar P) : +    ((points.Q side x z).postprocess Prod.fst).effect a = +      ∑ b, (points.Q side x z).effect (a, b) := by +  classical +  change (∑ pair ∈ Finset.univ.filter (fun pair => pair.1 = a), +    (points.Q side x z).effect pair) = _ +  simp only [Finset.sum_filter, Fintype.sum_prod_type] +  rw [Finset.sum_comm] +  simp + +/-- The second postprocessed joint-point effect is its Z marginal sum. +This formalization-only identity is `eq:qld-qxz-close-to-point-2`, paper +`references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:933-935`. -/ +theorem postprocess_snd_effect {P : AdmissibleParams} {ε δQ : ℝ} +    {S :