calar P × PauliScalar P) => +      phaseSign (fixedBinTrace P.model (ab.1 * rs.1)) * +        phaseSign (fixedBinTrace P.model (ab.2 * rs.2))) +    ((Fintype.card (PauliScalar P) : ℝ) ^ 2) +    (fun rs rs' => sum_pairCharacter_mul_pairCharacter rs rs') v +  have hq : (0 : ℝ) < (Fintype.card (PauliScalar P) : ℝ) := by +    exact_mod_cast Fintype.card_pos +  have hcnorm : ‖c * c‖ = ((Fintype.card (PauliScalar P) : ℝ) ^ 2)⁻¹ := by +    simp only [c, norm_mul, norm_inv, Complex.norm_natCast] +    rw [sq, mul_inv] +  calc ∑ ab : PauliScalar P × PauliScalar P, +        ‖applyOperatorToState (S.place p +          (S.expPointOp p.side .X x ab.1 * S.expPointOp p.side .Z z ab.2 - +            S.expPointOp p.side .Z z ab.2 * S.expPointOp p.side .X x ab.1)) +          S.psiHat‖ ^ 2 +      = ∑ ab : PauliScalar P × PauliScalar P, +          ‖c * c‖ ^ 2 * ‖∑ rs : PauliScalar P × PauliScalar P, +            (phaseSign (fixedBinTrace P.model (ab.1 * rs.1)) * +              phaseSign (fixedBinTrace P.model (ab.2 * rs.2))) • v rs‖ ^ 2 := by +        refine Finset.sum_congr rfl fun ab _ => ?_ +        rw [hpt, norm_smul, mul_pow] +    _ = ‖c * c‖ ^ 2 * (((Fintype.card (PauliScalar P) : ℝ) ^ 2) * +          ∑ rs, ‖v rs‖ ^ 2) := by +        rw [← Finset.mul_sum, hparseval] +    _ = avgOver (uniformDistribution (PauliScalar P × PauliScalar P)) +          (fun rs => ‖v rs‖ ^ 2) := by +        rw [avgOver_uniform_eq_inv_card_mul_sum, Fintype.card_prod, hcnorm] +        push_cast +        field_simp + +/-- The field-valued expanded point measurements approximately commute on each +of the four register placements, with the error of item 2 of +`lem:qld-comm-cons`.  The estimate is transferred from the binary refinements +of the source by the Parseval identity, without loss in the field size.  Paper +`references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:466-505`, +blueprint `blueprint/src/chapter/ch14_qpbt_observables.tex:1139-1210`; the +role of this form in the proof of `lem:qld-4-10` is explained in +`docs/paper-gaps/qpbt_linearity-theorem-quotation.tex`. -/ +theorem expPoint_comm : +    ∃ C : ℝ, 1 ≤ C ∧ +      ∀ (P : AdmissibleParams) (ε : ℝ) (S : ProjectiveSetting P ε) +        (p : Placement), +        opFamilyDistSq (uniformDistribution (PointPair P)) +          (fun xz (ab : PauliScalar P × PauliScalar P) => S.place p +            ((S.pointMeasExp p.side .X xz.1).effect ab.1 * +              (S.pointMeasExp p.side .Z xz.2).effect ab.2)) +          (fun xz ab => S.place p +            ((S.pointMeasExp p.side .Z xz.2).effect ab.2 * +              (S.pointMeasExp p.side .X xz.1).effect ab.1)) +          S.psiHat ≤ C * Real.sqrt ε := by +  obtain ⟨C, hC, h⟩ := exists_twistedCommutator_avg_le +  refine ⟨C, hC, ?_⟩ +  intro P ε S p +  have hε : (0 : ℝ) ≤ ε := by +    have hv := WinImplications.strategy_value_le_one S.toStrategy +    have hw := S.win +    linarith +  have hnorm : ∀ (x z : Fin P.m → PauliScalar P) +      (rs : PauliScalar P × PauliScalar P), +      ‖applyOperatorToState (S.place p +          (S.expObs p.side .X rs.1 x * S.expObs p.side .Z rs.2 z - +            S.expObs p.side .Z rs.2 z * S.expObs p.side .X rs.1 x)) +          S.psiHat‖ ^ 2 = +        ‖applyOperatorToState +          (S.placeStrategySide p.side (S.twistedCommutator p.side (x, z, rs.1, rs.2))) +          S.toStrategy.ψ‖ ^ 2 := by +    intro x z rs +    rw [expObs_commutator S p.side (x, z, rs.1, rs.2), +      norm_place_heteroKron_psiHat S p _ _ (tauX_mul_tauZ_isometry P (x, z, rs.1, rs.2))] +  have hfamily : opFamilyDistSq (uniformDistribution (PointPair P)) +      (fun xz (ab : PauliScalar P × PauliScalar P) => S.place p +        ((S.pointMeasExp p.side .X xz.1).effect ab.1 * +          (S.pointMeasExp p.side .Z xz.2).effect ab.2)) +      (fun xz ab => S.place p +        ((S.pointMeasExp p.side .Z xz.2).effect ab.2 * +          (S.pointMeasExp p.side .X xz.1).effect ab.1)) +      S.psiHat = +      avgOver (uniformDistribution (PauliTuple P)) (fun ω => +        ‖applyOperatorToState +          (S.placeStrategySide p.side (S.twistedCommutator p.side ω)) +          S.toStrategy.ψ‖ ^ 2) := by +    unfold opFamilyDistSq +    calc avgOver (uniformDistribution (PointPair P)) (fun xz => +          ∑ ab : PauliScalar P × PauliScalar P, +            ‖applyOperatorToState (S.place p +                ((S.pointMeasExp p.side .X xz.1).effect ab.1 * +                  (S.pointMeasExp p.side .Z xz.2).effect ab.2) - +              S.place p ((S.pointMeasExp p.side .Z xz.2).effect ab.2 * +                (S.pointMeasExp p.side .X xz.1).effect ab.1)) S.psiHat‖ ^ 2) +        = avgOver (uniformDistribution (PointPair P)) (fun xz => +            avgOver (uniformDistribution (PauliScalar P × PauliScalar P)) +              (fun rs => ‖applyOperatorToState +                (S.placeStrategySide p.side +                  (S.twistedCommutator p.side (xz.1, xz.2, rs.1, rs.2))) +                S.toStrategy.ψ‖ ^ 2)) := by +          refine avgOver_congr _ _ _ fun xz => ?_ +          rw [← avgOver_congr _ _ _ (hnorm xz.1 xz.2), +            ← sum_norm_place_expPointOp_commutator_sq S p xz.1 xz.2] +          refine Finset.sum_congr rfl fun ab _ => ?_ +          rw [place_sub] +          rfl +      _ = avgOver (uniformDistribution (PointPair P × (PauliScalar P × PauliScalar P))) +            (fun q => ‖applyOperatorToState +              (S.placeStrategySide p.side +                (S.twistedCommutator p.side (q.1.1, q.1.2, q.2.1, q.2.2))) +              S.toStrategy.ψ‖ ^ 2) := +          (avgOver_uniform_prod (fun (xz : PointPair P) +            (rs : PauliScalar P × PauliScalar P) => ‖applyOperatorToState +              (S.placeStrategySide p.side +                (S.twistedCommutator p.side (xz.1, xz.2, rs.1, rs.2))) +              S.toStrategy.ψ‖ ^ 2)).symm +      _ = avgOver (uniformDistribution (PauliTuple P)) (fun ω => +            ‖applyOperatorToState +              (S.placeStrategySide p.side (S.twistedCommutator p.side ω)) +              S.toStr