   exact_mod_cast Fintype.card_pos +  have hcnorm : ‖c * c‖ = ((Fintype.card (PauliScalar P) : ℝ) ^ 2)⁻¹ := by +    simp only [c, norm_mul, norm_inv, Complex.norm_natCast] +    rw [sq, mul_inv] +  calc ∑ ab : PauliScalar P × PauliScalar P, +        ‖applyOperatorToState (S.place p +          (S.expPointOp p.side .X x ab.1 * S.expPointOp p.side .Z z ab.2 - +            S.expPointOp p.side .Z z ab.2 * S.expPointOp p.side .X x ab.1)) +          S.psiHat‖ ^ 2 +      = ∑ ab : PauliScalar P × PauliScalar P, +          ‖c * c‖ ^ 2 * ‖∑ rs : PauliScalar P × PauliScalar P, +            (phaseSign (fixedBinTrace P.model (ab.1 * rs.1)) * +              phaseSign (fixedBinTrace P.model (ab.2 * rs.2))) • v rs‖ ^ 2 := by +        refine Finset.sum_congr rfl fun ab _ => ?_ +        rw [hpt, norm_smul, mul_pow] +    _ = ‖c * c‖ ^ 2 * (((Fintype.card (PauliScalar P) : ℝ) ^ 2) * +          ∑ rs, ‖v rs‖ ^ 2) := by +        rw [← Finset.mul_sum, hparseval] +    _ = avgOver (uniformDistribution (PauliScalar P × PauliScalar P)) +          (fun rs => ‖v rs‖ ^ 2) := by +        rw [avgOver_uniform_eq_inv_card_mul_sum, Fintype.card_prod, hcnorm] +        push_cast +        field_simp + +/-- The field-valued expanded point measurements approximately commute on each +of the four register placements, with the error of item 2 of +`lem:qld-comm-cons`.  The estimate is transferred from the binary refinements +of the source by the Parseval identity, without loss in the field size.  Paper +`references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:466-505`, +blueprint `blueprint/src/chapter/ch14_qpbt_observables.tex:1139-1210`; the +role of this form in the proof of `lem:qld-4-10` is explained in +`docs/paper-gaps/qpbt_linearity-theorem-quotation.tex`. -/ +theorem expPoint_comm : +    ∃ C : ℝ, 1 ≤ C ∧ +      ∀ (P : AdmissibleParams) (ε : ℝ) (S : ProjectiveSetting P ε) +        (p : Placement), +        opFamilyDistSq (uniformDistribution (PointPair P)) +          (fun xz (ab : PauliScalar P × P