one-sided pasting estimate on independent Alice and Bob spaces. +This is a stronger Lean-only auxiliary for paper `lem:pasting`, +`references/qpbt-paper/06_nonlocal_games_and_mipstar.tex:504-525`: only its two +forward marginal comparisons are required. The paper-facing +`exists_pasting_error` continues to retain all three printed hypotheses. + +The two spaces embed isometrically into a common product carrier by adjoining +fixed unit basis vectors. Tensor placement preserves the measurements and their +projectivity; `Pasting.consistencyDefect_productPaddedState` preserves the input +and output defects. The unit state internally excludes empty local carriers; +no nonemptiness assumption on outcomes is needed. See issue #495 and blueprint +`lem:pasting-heterogeneous`. + +**Local fix:** the additive interpretation of `IsPolyErr₂` is documented in +`docs/paper-gaps/qpbt_pasting-product-error.tex`, issue #201. -/ +theorem exists_pasting_error_heterogeneous : +    ∃ δp : ℝ → ℝ → ℝ, IsPolyErr₂ δp ∧ +      ∀ {X Y₁ Y₂ R₁ R₂ Γ₁ Γ₂ ιA ιB : Type*} +        [Fintype X] [DecidableEq X] [Fintype Y₁] [DecidableEq Y₁] +        [Fintype Y₂] [DecidableEq Y₂] [Fintype R₁] [DecidableEq R₁] +        [Fintype R₂] [DecidableEq R₂] +        [Fintype Γ₁] [DecidableEq Γ₁] [Fintype Γ₂] [DecidableEq Γ₂] +        [Fintype ιA] [DecidableEq ιA] [Fintype ιB] [DecidableEq ιB] +        (D : Distribution ((X × Y₁) × Y₂)) +        (eval₁ : Γ₁ → Y₁ → R₁) (eval₂ : Γ₂ → Y₂ → R₂) +        (G₁ : X → Measurement Γ₁ ιB) (G₂ : X → Measurement Γ₂ ιB) +        (A : ((X × Y₁) × Y₂) → Measurement (R₁ × R₂) ιA) +        (ψ : EuclideanSpace ℂ (ιA × ιB)) (η δ : ℝ), +        D.IsProbability → ‖ψ‖ = 1 → 0 ≤ η → 0 ≤ δ → +        (∀ x, MIPStarRE.QPBT.Measurement.IsProjective (G₂ x)) → +        (∀ q, MIPStarRE.QPBT.Measurement.IsProjective (A q)) → +        HasConditionalCollisionBound D eval₂ η → +        consistencyDefect D +          (fun q a₁ => heteroKron (((A q).postprocess Prod.fst).effect a₁) 1) +          (fun q a₁ => heteroKron 1 (((G₁ q.1.1).postprocess +            (fun g => eval₁ g q.1.2)).effect a₁)) ψ ≤ δ → +        consistencyDefect D +          (fun q a₂ => heteroKron (((A q).postprocess Prod.snd).effect a₂) 1) +          (fun q a₂ => heteroKron 1 (((G₂ q.1.1).postprocess +            (fun g => eval₂ g q.2)).effect a₂)) ψ ≤ δ → +        consistencyDefect D (fun q a => heteroKron ((A q).effect a) 1) +          (fun q a => heteroKron 1 (∑ g₁ : Γ₁, ∑ g₂ : Γ₂, +            if (eval₁ g₁ q.1.2, eval₂ g₂ q.2) = a then +              pastedMeasurement (fun g => (G₁ q.1.1).effect g) +                (fun g => (G₂ q.1.1).effect g) g₁ g₂ else 0)) ψ ≤ δp η δ := by +  classical +  obtain ⟨δp, hpoly, hbound⟩ := exists_pasting_error_of_marginal_consistency +  refine ⟨δp, hpoly, ?_⟩ +  intro X Y₁ Y₂ R₁ R₂ Γ₁ Γ₂ ιA ιB _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ +    D eval₁ eval₂ G₁ G₂ A ψ η δ hD hψ hη hδ hG₂ hA hcoll h₁ h₂ +  have hnonempty : Nonempty (ιA × ιB) := by +    rcases isEmpty_or_nonempty (ιA × ιB) with h | h +    · letI := h +      have hz : ψ = 0 := Subsingleton.elim _ _ +      simp [hz] at hψ +    · exact h +  obtain ⟨⟨a₀, b₀⟩⟩ := hnonempty +  let A' := fun q => Measurement.leftPlacement (ιB := ιB) (A q) +  let G₁' := fun x => Measurement.rightPlacement (ιA := ιA) (G₁ x) +  let G₂' := fun x => Measurement.rightPlacement (ιA := ιA) (G₂ x) +  let ψ' := Pasting.productPaddedState a₀ b₀ ψ +  have hψ' : ‖ψ'‖ = 1 := (Pasting.productPaddedState_norm a₀ b₀ ψ).trans hψ +  have h₁' : consistencyDefect D +      (fun q a₁ => heteroKron (((A' q).postprocess Prod.fst).effect a₁) 1) +      (fun q a₁ => heteroKron 1 (((G₁' q.1.1).postprocess +        (fun g => eval₁ g q.1.2)).effect a₁)) ψ' ≤ δ := by +    simpa only [A', G₁', ψ', ← Measurement.leftPlacement_postprocess, +      ← Measurement.rightPlacement_postprocess, Measurement.leftPlacement_effect, +      Measurement.rightPlacement_effect, Pasting.consistencyDefect_productPaddedState] using h₁ +  have h₂' : consistencyDefect D +      (fun q a₂ => heteroKron (((A' q).postprocess Prod.snd).effect a₂) 1) +      (fun q a₂ => heteroKron 1 (((G₂' q.1.1).postprocess +        (fun g => eval₂ g q.2)).effect a₂)) ψ' ≤ δ := by +    simpa only [A', G₂', ψ', ← Measurement.leftPlacement_postprocess, +      ← Measurement.rightPlacement_postprocess, Measurement.leftPlacement_effect, +      Measurement.rightPlacement_effect, Pasting.consistencyDefect_productPaddedState] using h₂ +  have hpadded := hbound D eval₁ eval₂ G₁' G₂' A' ψ' η δ hD hψ' hη hδ +    (fun x => Measurement.isProjective_rightPlacement (G₂ x) (hG₂ x)) +    (fun q => Measurement.isProjective_leftPlacement (A q) (hA q)) hcoll h₁' h₂' +  have hpaste (q : (X × Y₁) × Y₂) (a : R₁ × R₂) : +      (∑ g₁ : Γ₁, ∑ g₂ : Γ₂, +        if (eval₁ g₁ q.1.2, eval₂ g₂ q.2) = a then +          pastedMeasurement (fun g => (G₁' q.1.1).effect g) +            (fun g => (G₂' q.1.1).effect g) g₁ g₂ else 0) = +        heteroKron (1 : Op ιA) (∑ g₁ : Γ₁, ∑ g₂ : Γ₂, +          if (eval₁ g₁ q.1.2, eval₂ g₂ q.2) = a then +            pastedMeasurement (fun g => (G₁ q.1.1).effect g) +              (fun g => (G₂ q.1.1).effect g) g₁ g₂ else 0) := by +    simp only [G₁', G₂', Measurement.rightPlacement_effect, pastedMeasurement, +      heteroKron_mul, one_mul] +    simp_rw [heteroKron_finset_sum_right] +    apply Finset.sum_congr rfl +    intro g₁ _ +    apply Finset.sum_congr rfl +    intro g₂ _ +    split_ifs <;> simp [heteroKron, Matrix.kronecker] +  simp_rw [hpaste] at hpadded +  simpa only [A', ψ', Measurement.leftPlacement_effect, +    Pasting.consistencyDefect_productPaddedState] using hpadded + +end MIPStarRE.QPBT diff --git a/audits/2026-09-09-qpbt-heterogeneous-pasting.md b/audits/2026-09-09-qpbt-heterogeneous-pasting.md new file mode 100644 index 00000000..b9b40c67 --- /dev/null +++ b/audits/2026-09-09-qpbt-heterogeneous-pasting.md @@ -0,0 +1,72 @@ +# Heterogeneous Pasting: Statement Integrity + +This audit concerns issue #495 and paper `lem:pasting`, +`references/qpbt-paper/06_nonlocal_games_and_mipstar.tex:504-525`. +Its intended application is `lem:qld-xz-lines`, +`14_analysis_of_the_pauli_basis_test.tex:882-963`. + +## Source Theorem + +The paper assumes a probability distribution on triples `(x,y1,y2)`, two +codeword evaluation maps, measurement families `G1,G2`, and a joint projective +measurement family `A`. The family `G2` is projective. Distinct second +codewords collide with conditional probability at most `eta`, conditioned on +each pair `(x,y1)` of positive marginal probability. Both marginals of `A` +are consistent with the corresponding evaluated codeword family to error +`delta`; the joint family `A` also satisfies the printed self-consistency +comparison. The state is normalized and the error parameters are nonnegative. + +The conclusion compares `A` with the evaluated sandwich `G2 G1 G2`, with one +universal polynomial error function of `(eta,delta)`. The existing additive +interpretation of this polynomial error is unchanged; its justification is +`docs/paper-gaps/qpbt_pasting-product-error.tex`, issue #201. + +The public Lean statement `exists_pasting_error` is unchanged. All paper +hypotheses, including the third comparison, and the conclusion are retained. +Its proof is now a corollary of an extracted two-comparison proof. +The declaration `pastedMeasurement_isMeasurement` is moved without any change +to its statement or proof. Verdict: exact preservation of both existing +statements, with their previously documented finite-dimensional encoding and +additive-error correction. + +## Stronger Auxiliary Statements + +The extracted `exists_pasting_error_of_marginal_consistency` has the original +homogeneous conclusion and all hypotheses except the third comparison. This +is justified because the existing Schmidt-mirror argument does not use that +comparison. The mathematical proof is retained once, rather than duplicated. + +The new `exists_pasting_error_heterogeneous` also assumes only the two forward +marginal comparisons. Alice and Bob have independent finite carriers. The +distribution, evaluation maps, projectivity conditions, conditional collision +bound, normalized state, nonnegative errors, universal error quantifier, and +pasted conclusion agree with the extracted homogeneous statement. There is +no dimension equality, carrier equivalence, register-exchange assumption, or +unproved intermediate hypothesis. Verdict: stronger auxiliary theorem, with +weaker assumptions and an unchanged conclusion; it is recorded in its own +blueprint entry, not as a replacement for the source-labelled theorem. + +The literal third homogeneous comparison cannot be placed on independent +carriers using a single Alice measurement. No artificial Bob measurement is +introduced. The original paper-facing statement continues to display that +comparison in its well-typed homogeneous setting. + +## Common-Space Realization + +Let the original spaces be `HA` and `HB`. Choose unit coordinate vectors +`a0` and `b0` and use the common space `K = HA tensor HB` on each side. +Alice's operators become `A tensor I`, and Bob's become `I tensor B`. +The new bipartite state has coefficients +`Psi((i,b),(a,j)) = [b=b0] [a=a0] psi(i,j)`. + +Direct finite-sum calculations prove equality of norms and of all bipartite +quadratic forms. Consequently the input consistency defects and the pasted +output defect are equal before and after this realization. Existing tensor +placement theorems preserve POVMs, projectivity, and postprocessing; tensor +multiplicativity preserves the sandwich. The distribution and collision +condition are untouched. A unit state rules out an empty product carrier, +so local nonemptiness is derived internally. No outcome nonemptiness is used. + +These constructions are closed Lean proofs and introduce no proof holes or +additional axioms. They do not assert an isomorphism between the original +matrix algebras of unequal dimensions. diff --git a/blueprint/src/chapter/ch12_qpbt_games.tex b/blueprint/src/chapter/ch12_qpbt_games.tex index 91cbea81..d7c04a06 100644 --- a/blueprint/src/chapter/ch12_qpbt_games.tex +++ b/blueprint/src/chapter/ch12_qpbt_games.tex @@ -1038,6 +1038,25 @@ postprocessing, and operator-contraction steps used to formalize  ?\end{equation}  ?Neither the exponent nor the constant in $\poly(\eta, \delta)$ is made explicit in the source; both are universal constants inherited from the proof of Fact 4.35 in \cite{Natarajan2018NEEXP}. The literal product-form convention for this notation is incompatible with the unrestricted error domain in the lemma; a two-dimensional counterexample and the required correction are recorded in \cite{gap:qpbt_pasting-product-error}.  \end{lemma} +\begin{proof} +?\leanok +?\uses{lem:pasting-forward-comparisons} +?Apply Lemma~\ref{lem:pasting-forward-comparisons} to the two marginal +?comparisons~\eqref{eq:pasting-1}. These suffice for the pasted conclusion; +?the self-consistency comparison~\eqref{eq:pasting-2} is not needed. +\end{proof} + +\begin{lemma}[Pasting from the forward comparisons] +?\label{lem:pasting-forward-comparisons} +?\lean{MIPStarRE.QPBT.exists_pasting_error_of_marginal_consistency} +?\leanok +?\uses{def:consistency, def:bracket, def:povm-conventions} +?This formalization-only strengthening of Lemma~\ref{lem:pasting} has the +?same conclusion under its projectivity and conditional collision hypotheses +?and the two forward comparisons~\eqref{eq:pasting-1}, for a unit state and +?$\eta,\delta\geq0$. The self-consistency comparison~\eqref{eq:pasting-2} +?is not required. The local carrier is common to both players. +\end{lemma}  \begin{proof}  ?\leanok  ?\uses{lem:pasting-one-sided-explicit-error, lem:pasting-coarse-commutator, @@ -1054,6 +1073,75 @@ postprocessing, and operator-contraction steps used to formalize  ?in \cite{gap:qpbt_pasting-product-error}, not the refuted product contract.  \end{proof}   +\begin{definition}[Adjoining fixed basis vectors] +?\label{def:pasting-product-state} +?\lean{MIPStarRE.QPBT.Pasting.productPaddedState} +?\leanok +?Let $\mathcal H_A=\mathbb C^{I_A}$ and $\mathcal H_B=\mathbb C^{I_B}$, +?where $I_A,I_B$ are finite, and fix $a_0\in I_A$, $b_0\in I_B$. +?For $\psi\in\mathcal H_A\otimes\mathcal H_B$, define a vector on +?$(\mathcal H_A\otimes\mathcal H_B)^{\otimes2}$ by +?\[ +??\Psi_{(i,b),(a,j)} +??=\mathbf 1_{b=b_0}\mathbf 1_{a=a_0}\psi_{i,j}. +?\] +?This is a formalization-only common-space realization for +?Lemma~\ref{lem:pasting}. +\end{definition} + +\begin{lemma}[Preservation under adjoining basis vectors] +?\label{lem:pasting-product-state-preservation} +?\lean{MIPStarRE.QPBT.Pasting.productPaddedState_norm} +?\lean{MIPStarRE.QPBT.Pasting.stateQForm_productPaddedState} +?\lean{MIPStarRE.QPBT.Pasting.consistencyDefect_productPaddedState} +?\leanok +?\uses{def:pasting-product-state, def:consistency} +?For the preceding construction, $\|\Psi\|=\|\psi\|$. For arbitrary +?operators $A$ on $\mathcal H_A$ and $B$ on $\mathcal H_B$, +?\[ +??\operatorname{Re}\langle\Psi, +?? ((A\otimes\Id)\otimes(\Id\otimes B))\Psi\rangle +??=\operatorname{Re}\langle\psi,(A\otimes B)\psi\rangle. +?\] +?Consequently every averaged off-diagonal consistency defect is preserved +?by these local placements, for arbitrary operator families and any finite +?distribution. Positivity and state normalization are not required. +\end{lemma} +\begin{proof} +?\leanok +?\uses{def:pasting-product-state} +?Expand the norm and quadratic form in the standard bases. The fixed +?coordinates remove two sums. Sum the quadratic-form identity over unequal +?answers and average over the question distribution. +\end{proof} + +\begin{lemma}[Pasting on independent local spaces] +?\label{lem:pasting-heterogeneous} +?\lean{MIPStarRE.QPBT.exists_pasting_error_heterogeneous} +?\leanok +?\uses{def:consistency, def:bracket, def:povm-conventions} +?There is a universal function +?$\delta_{\mathrm{pasting}}(\eta,\delta)=\poly(\eta,\delta)$ for which +?Lemma~\ref{lem:pasting