.X x a * S.expPointOp side .Z z b - +        S.expPointOp side .Z z b * S.expPointOp side .X x a = +      ((Fintype.card (PauliScalar P) : ℂ)⁻¹ * +          (Fintype.card (PauliScalar P) : ℂ)⁻¹) • +        ∑ rs : PauliScalar P × PauliScalar P, +          (phaseSign (fixedBinTrace P.model (a * rs.1)) * +              phaseSign (fixedBinTrace P.model (b * rs.2))) • +            (S.expObs side .X rs.1 x * S.expObs side .Z rs.2 z - +              S.expObs side .Z rs.2 z * S.expObs side .X rs.1 x) := by +  rw [expPointOp_eq_inv_card_smul_sum, expPointOp_eq_inv_card_smul_sum, +    smul_sum_mul_smul_sum, smul_sum_mul_smul_sum_swap, ← smul_sub, +    ← Finset.sum_sub_distrib] +  congr 1 +  refine Finset.sum_congr rfl fun rs _ => ?_ +  rw [smul_sub] + +/-- Formalization-only auxiliary: an operator applied to a state is linear in +the operator over finite sums. -/ +theorem applyOperatorToState_finsetSum {ι γ : Type*} [Fintype ι] [DecidableEq ι] +    (s : Finset γ) (M : γ → Op ι) (ψ : EuclideanSpace ℂ ι) : +    applyOperatorToState (∑ x ∈ s, M x) ψ = +      ∑ x ∈ s, applyOperatorToState (M x) ψ := by +  unfold applyOperatorToState +  simp only [map_sum, LinearMap.sum_apply] + +/-- Parseval transfer, pointwise in the point pair: the summed squared norms of +the placed commutators of the field-valued point effects equal the average over +`(r, s)` of the squared norms of the placed commutators of the expanded +observables. -/ +theorem sum_norm_place_expPointOp_commutator_sq (S : ProjectiveSetting P ε) +    (p : Placement) (x z : Fin P.m → PauliScalar P) : +    ∑ ab : PauliScalar P × PauliScalar P, +        ‖applyOperatorToState (S.place p +          (S.expPointOp p.side .X x ab.1 * S.expPointOp p.side .Z z ab.2 - +            S.expPointOp p.side .Z z ab.2 * S.expPointOp p.side .X x ab.1)) +          S.psiHat‖ ^ 2 = +      avgOver (uniformDistribution (PauliScalar P × PauliScalar P)) +        (fun rs => ‖applyOperatorToState (S.place p +          (S.expObs p.side .X rs.1 x * S.expO