is vectors preserves the state norm. Formalization-only +auxiliary, blueprint `lem:pasting-product-state-preservation`. -/ +theorem productPaddedState_norm (a₀ : ιA) (b₀ : ιB) +    (ψ : EuclideanSpace ℂ (ιA × ιB)) : +    ‖productPaddedState a₀ b₀ ψ‖ = ‖ψ‖ := by +  rw [← sq_eq_sq₀ (norm_nonneg _) (norm_nonneg _)] +  simp [EuclideanSpace.norm_sq_eq, productPaddedState, Fintype.sum_prod_type, apply_ite] + +/-- Local tensor padding preserves every bipartite quadratic form. This exact +identity is independent of positivity and of normalization of the state. +Formalization-only auxiliary, blueprint `lem:pasting-product-state-preservation`. -/ +theorem stateQForm_productPaddedState (a₀ : ιA) (b₀ : ιB) +    (ψ : EuclideanSpace ℂ (ιA × ιB)) (A : Op ιA) (B : Op ιB) : +    stateQForm (productPaddedState a₀ b₀ ψ) +        (heteroKron (heteroKron A (1 : Op ιB)) (heteroKron (1 : Op ιA) B)) = +      stateQForm ψ (heteroKron A B) := by +  unfold stateQForm applyOperatorToState +  rw [EuclideanSpace.inner_eq_star_dotProduct, EuclideanSpace.inner_eq_star_dotProduct] +  apply congrArg Complex.re +  simp [productPaddedState, Matrix.toEuclideanLin, Matrix.mulVec, dotProduct, +    heteroKron, Matrix.kronecker, Matrix.kroneckerMap_apply, Fintype.sum_prod_type, +    Matrix.one_apply, Finset.sum_mul, apply_ite] + +/-- Tensor padding preserves the off-diagonal consistency defect for arbitrary +operator families. No measurement or probability assumption is required. +Formalization-only auxiliary, blueprint `lem:pasting-product-state-preservation`. -/ +theorem consistencyDefect_productPaddedState {X α : Type*} +    [Fintype X] [DecidableEq X] [Fintype α] [DecidableEq α] +    (D : Distribution X) (A : X → α → Op ιA) (B : X → α → Op ιB) +    (a₀ : ιA) (b₀ : ιB) (ψ : EuclideanSpace ℂ (ιA × ιB)) : +    consistencyDefect D +        (fun x a => heteroKron (heteroKron (A x a) (1 : Op ιB)) (1 : Op (ιA × ιB))) +        (fun x a => heteroKron (1 : Op (ιA × ιB)) (heteroKron (1 : Op ιA) (B x a))) +       